<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/app/helpers/industry-forums.php';
$user=require_role('admin','staf_bkk');$ready=industry_forums_ready();$q=input_text($_GET,'q');$fromDate=input_text($_GET,'dari');$toDate=input_text($_GET,'sampai');
if(!valid_text($q,100,false)||($fromDate!==''&&!pkl_date($fromDate))||($toDate!==''&&!pkl_date($toDate))||($fromDate!==''&&$toDate!==''&&$fromDate>$toDate)){http_response_code(400);exit('Filter sarasehan tidak valid.');}
$where='1=1';$params=[];
if($q!==''){$where.=" AND nama LIKE :nama ESCAPE '!'";$params['nama']='%'.str_replace(['!','%','_'],['!!','!%','!_'],$q).'%';}
if($fromDate!==''){$where.=' AND tanggal>=:dari';$params['dari']=$fromDate;}if($toDate!==''){$where.=' AND tanggal<=:sampai';$params['sampai']=$toDate;}
$total=$ready?(int)panel_query('SELECT COUNT(*) FROM industry_forums WHERE '.$where,$params)->fetchColumn():0;$pages=max(1,(int)ceil($total/10));$page=min($pages,positive_id($_GET['page']??'1')??1);
$rows=$ready?panel_query('SELECT * FROM industry_forums WHERE '.$where.' ORDER BY tanggal,jam,id LIMIT :limit OFFSET :offset',$params+['limit'=>10,'offset'=>($page-1)*10])->fetchAll():[];
panel_start($user,'Sarasehan Industri','sarasehan');
?>
<div class="forum-list-page">
<header class="partner-detail-heading"><h1><?= panel_icon('calendar') ?> Jadwal Sarasehan Industri</h1><nav aria-label="Pengelolaan sarasehan"><?php if($ready): ?><a class="forum-add" href="<?= e(base_url('panel/sarasehan/form.php')) ?>"><?= panel_icon('add') ?> Tambah jadwal</a><?php endif; ?></nav></header>
<?php if(!$ready): ?><p class="notice">Impor database/updates/023_industry_forums_ideas.sql untuk mengaktifkan modul.</p><?php endif; ?>
<form class="filter-form card" method="get"><label><span><?= panel_icon('search') ?> Cari kegiatan</span><input name="q" maxlength="100" value="<?= e($q) ?>"></label><label><span><?= panel_icon('calendar') ?> Dari tanggal</span><input name="dari" type="date" value="<?= e($fromDate) ?>"></label><label><span><?= panel_icon('calendar') ?> Sampai tanggal</span><input name="sampai" type="date" value="<?= e($toDate) ?>"></label><button type="submit"><?= panel_icon('search') ?> Cari</button><a href="<?= e(base_url('panel/sarasehan/')) ?>"><?= panel_icon('reset') ?> Reset</a></form>
<div class="forum-table-heading"><h2><?= panel_icon('berita') ?> Daftar kegiatan</h2><span><?= $total ?> kegiatan &middot; Halaman <?= $page ?> dari <?= $pages ?></span></div>
<div class="table-scroll forum-list-sheet" data-vertical-list tabindex="0" role="region" aria-label="Jadwal sarasehan, gulir untuk melihat data"><table><thead><tr><th><span><?= panel_icon('berita') ?> Nama kegiatan</span></th><th><span><?= panel_icon('calendar') ?> Jadwal WIB</span></th><th><span><?= panel_icon('location') ?> Lokasi / pertemuan</span></th><th><span><?= panel_icon('akun') ?> PIC sekolah</span></th><th><span><?= panel_icon('pengaturan') ?> Tindakan</span></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= e($row['nama']) ?></td><td><span class="forum-date"><?= e($row['tanggal']) ?></span><small><?= e(substr($row['jam'],0,5)) ?> WIB</small></td><td><?= e($row['lokasi']?:'Pertemuan daring') ?><?php if($row['tautan']&&http_url($row['tautan'])): ?><br><a href="<?= e($row['tautan']) ?>" target="_blank" rel="noopener noreferrer">Tautan pertemuan</a><?php endif; ?></td><td><?= e($row['pic_sekolah']) ?></td><td><div class="forum-row-actions"><a class="forum-view" href="<?= e(base_url('panel/sarasehan/detail.php?id='.$row['id'])) ?>"><?= panel_icon('view') ?> Detail</a><a class="forum-edit" href="<?= e(base_url('panel/sarasehan/form.php?id='.$row['id'])) ?>"><?= panel_icon('edit') ?> Edit</a></div></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5"><?= $q!==''||$fromDate!==''||$toDate!==''?'Tidak ada kegiatan sesuai filter.':'Belum ada jadwal sarasehan.' ?></td></tr><?php endif; ?></tbody></table></div>
<nav class="pagination" aria-label="Halaman sarasehan"><?php foreach(['Sebelumnya'=>$page-1,'Berikutnya'=>$page+1] as $label=>$target):if($target<1||$target>$pages){continue;} ?><a href="<?= e(base_url('panel/sarasehan/?'.http_build_query(['q'=>$q,'dari'=>$fromDate,'sampai'=>$toDate,'page'=>$target]))) ?>"><?= $label ?></a><?php endforeach; ?></nav>
</div>
<?php panel_end($user); ?>
